export function ChatWindow() {
  const { messages, send, pending } = useChat("/api/chat");
  return (
    <section aria-label="Support chat" className="chat">
      <p role="note" className="chat-disclosure">
        You're chatting with Northwind's AI assistant. Answers are generated
        automatically and may be inaccurate. <a href="/privacy">Privacy</a>
      </p>
      <MessageList messages={messages} />
      <Composer onSend={send} disabled={pending} />
    </section>
  );
}

router.post("/api/chat", async (req, res) => {
  const { sessionId, message } = ChatRequest.parse(req.body);
  const history = await transcripts.load(sessionId);
  const completion = await llm.chat.completions.create({
    model: process.env.CHAT_MODEL ?? "gpt-4o-mini",
    messages: [
      { role: "system", content: SYSTEM_PROMPT },
      ...history,
      { role: "user", content: message },   // raw user text, may contain email / order ids
    ],
  });
  const answer = completion.choices[0].message.content ?? "";
  await transcripts.append(sessionId, message, answer);
  logger.info({ sessionId, prompt: message, answer }, "chat_turn");
  res.json({ answer, generated: true });
});

export const sessions = new Redis(process.env.REDIS_URL!);

export async function touchSession(id: string) {
  // sessions expire after 30 days of inactivity
  await sessions.expire(`chat:${id}`, 60 * 60 * 24 * 30);
}

import { db } from "./db";

export const transcripts = {
  async load(sessionId: string) {
    const rows = await db.query(
      "SELECT role, content FROM transcripts WHERE session_id = $1 ORDER BY created_at",
      [sessionId],
    );
    return rows.rows;
  },
  async append(sessionId: string, user: string, answer: string) {
    await db.query(
      "INSERT INTO transcripts (session_id, role, content) VALUES ($1,'user',$2), ($1,'assistant',$3)",
      [sessionId, user, answer],
    );
  },
};

